export function tripPartnerLink(lang: LinkLang, kind: PartnerLinkKind, cityId?: string): string {
  if (kind === 'hotel' && cityId && cityHotelLinks[cityId]) return cityHotelLinks[cityId][lang];
  if (kind === 'tours' && cityId && cityTourLinks[cityId]) return cityTourLinks[cityId][lang];
  return links[lang][kind] ?? links.en[kind];
}

export function hasCitySpecificPartnerLink(kind: PartnerLinkKind, cityId?: string): boolean {
  if (!cityId) return false;
  if (kind === 'hotel') return Boolean(cityHotelLinks[cityId]);
  if (kind === 'tours') return Boolean(cityTourLinks[cityId]);
  return false;
}
